use super::*;
#[path="../../tools/native-resource-adapter.rs"]mod adapter;
use std::{fs,path::Path};use serde_json::{json,Value};
fn byte_pin(v:&Value)->BytePin{let h=v["sha256"].as_str().unwrap();let mut sha256=[0;32];for(i,b)in sha256.iter_mut().enumerate(){*b=u8::from_str_radix(&h[i*2..i*2+2],16).unwrap();}BytePin{bytes:v["bytes"].as_u64().unwrap(),sha256}}
#[test]#[ignore = "requires: local evidence roots (snapshot JSON holds absolute D:\\ paths + SHA pins; only runnable on the original machine)"] fn complete_base_text_campaign_members_parse_source_fields_without_live_language_or_timer_grant(){
 let project=Path::new(env!("CARGO_MANIFEST_DIR"));let inventory:Value=serde_json::from_slice(&fs::read(project.join("logs/continuation-20261003/r473-complete-campaign-inventory.json")).unwrap()).unwrap();let mut facts=vec![];let mut negative=0;let mut contents=std::collections::BTreeMap::new();let(mut actual_members,mut indexed_rows)=(0,0);let mut selected=None;
 for pair in inventory["pairs"].as_array().unwrap(){let archive=pair["archives"].as_array().unwrap();let root=Path::new(archive[0]["snapshot"]["path"].as_str().unwrap()).parent().unwrap();let ns=pair["namespace"].as_str().unwrap();let read=|p:&Value|{let mut p=p.clone();p["namespace"]=json!(ns);adapter::read_pinned(root,&p,ns,64*1024*1024).unwrap()};let idx=read(&archive[0]["snapshot"]);let pak=read(&archive[1]["snapshot"]);let ip=byte_pin(&archive[0]["snapshot"]);let pp=byte_pin(&archive[1]["snapshot"]);indexed_rows+=pair["index_count"].as_u64().unwrap();
  if ns=="NATIVE_LITO_LTTEXT_V1"{assert!(pair["campaign_members"].as_array().unwrap().is_empty());assert!(inspect(true,Namespace::LitoLtText,&idx,&pak,ip,pp,"campaignDesc-e.tbl").is_err());negative+=1;continue;}
  for member in pair["campaign_members"].as_array().unwrap(){let name=member["name"].as_str().unwrap();let table=inspect(true,Namespace::OriginalBaseText,&idx,&pak,ip,pp,name).unwrap();let q=&table.provenance;assert_eq!(q.record_index,member["record_index"].as_u64().unwrap() as usize);assert_eq!(q.offset,member["offset"].as_u64().unwrap() as usize);assert_eq!(q.member,name);assert_eq!(q.raw_pin,byte_pin(&member["raw"]));assert_eq!(q.decoded_pin,byte_pin(&member["decoded"]));let fields=table.source_fields().unwrap();assert_eq!((fields.cycle_seconds,fields.lead_seconds,fields.message_count,fields.secondary_seconds),(3600,600,5,3000));assert_eq!((fields.finish_delay_ms,fields.start_delay_ms,fields.secondary_delay_ms),(600000,3000000,3000000));let suffix=name.as_bytes()[13];assert_eq!(fields.count,if suffix==b'c'{14}else{13});assert_eq!(fields.initializer_divisor,if suffix==b'c'{2}else{1});
   let bytes=fs::read(member["decoded"]["path"].as_str().unwrap()).unwrap();assert_eq!(parse(&bytes).unwrap(),table.rows);if let Some(old)=contents.insert(name.to_owned(),q.decoded_pin){assert_eq!(old,q.decoded_pin,"two baseversions haveidentical correspondingdecoded bytes");}if selected.is_none(){selected=Some((idx.clone(),pak.clone(),ip,pp,bytes.clone()));}facts.push(json!({"pair":pair["id"],"name":name,"record_index":q.record_index,"offset":q.offset,"raw_pin":member["raw"],"decoded_pin":member["decoded"],"count":fields.count,"numeric_fields":[fields.cycle_seconds,fields.lead_seconds,fields.message_count,fields.secondary_seconds],"delay_milliseconds":[fields.finish_delay_ms,fields.start_delay_ms,fields.secondary_delay_ms],"initializer_divisor":fields.initializer_divisor,"row_indices":(0..table.rows.len()).collect::<Vec<_>>(),"row_hex":table.rows.iter().map(|v|adapter::hex(v)).collect::<Vec<_>>() }));actual_members+=1;
  }
 }
 assert_eq!((indexed_rows,actual_members,contents.len()),(75140,10,5));let(index,pak,ip,pp,bytes)=selected.unwrap();assert!(inspect(false,Namespace::OriginalBaseText,&index,&pak,ip,pp,"campaignDesc-c.tbl").is_err());negative+=1;let mut wrong=ip;wrong.sha256[0]^=1;assert!(inspect(true,Namespace::OriginalBaseText,&index,&pak,wrong,pp,"campaignDesc-c.tbl").is_err());negative+=1;let mut wrong=pp;wrong.bytes+=1;assert!(inspect(true,Namespace::OriginalBaseText,&index,&pak,ip,wrong,"campaignDesc-c.tbl").is_err());negative+=1;assert!(inspect(true,Namespace::OriginalBaseText,&index,&pak,ip,pp,"../../campaignDesc-c.tbl").is_err());negative+=1;
 for bad in [b"0\n".to_vec(),b"32768\n".to_vec(),b"2\n0 a\n0 b\n".to_vec(),b"1\n1 a\n".to_vec(),b"2\n0 a\n".to_vec(),b"1\n0 \n".to_vec(),b"1\n0 a\0\n".to_vec(),b"1\n0 a".to_vec(),b"1\n-1 a\n".to_vec(),[b"1\n0 ".as_slice(),vec![b'x';255].as_slice(),b"\n"].concat()]{assert!(parse(&bad).is_err());negative+=1;}
 let mut sparse=bytes.clone();let start=sparse.windows(6).position(|v|v==b"0 3600").unwrap();sparse[start]=b'9';assert!(parse(&sparse).is_err());negative+=1;
 for code in 0..=65535u32{assert_eq!(language(code),match code{932=>b'j',936=>b'h',949=>b'k',950=>b'c',_=>b'e'});assert_eq!(campaign_gate(false,code),matches!(code,949|1252));assert!(!campaign_gate(true,code));}assert_eq!(language(1252),b'e');let eligible=json!({"949":"k","1252":"e"});
 fs::write(project.join("logs/continuation-20261003/r473-campaign-resource-details.json"),serde_json::to_vec_pretty(&json!({"state":"COMPLETE_ORIGINAL_BASE_CAMPAIGN_TABLES_PARSED_AND_SOURCE_LANGUAGE_GATE_VERIFIED_BYTES_ONLY","pairs":3,"indexed_rows":indexed_rows,"actual_members":actual_members,"language_variants":5,"member_facts":facts,"negative_cases":negative,"language_gate_comparisons":65536,"gate_eligible_languages":eligible,"raw_and_decoded_versions_identical":true,"all_rows_complete_nonempty_unique":true,"unrelated_archive_duplicate_rows_preserved":true,"original_base647980_namespace_required":true,"default_disabled":true,"conditional_600000_3000000_delays_not_dispatched":true,"eligible_initializer_divisor1_remainder0_implies_index11_if_initialized":true,"no_live_language_pointer_index_or_unload_grant":true,"R472_move5096_5263_5430_executed":false,"runtime_inputs_observed":false,"external_provider_executed":false,"native_callback_executed":false,"historical_focused_tests_rerun":0,"renderer_LOADED":false,"GUI":0})).unwrap()).unwrap();
}
